await page.getByRole('link',{name:'Women',exact:true}).first().click();
await page.waitForTimeout(2000);
const t=await page.locator('body').innerText();
const rows=t.split('\n').filter(r=>/^\d+\t/.test(r)).map(r=>r.split('\t'));
const c=rows.filter(r=>r[2].trim()=='CHN');
return [page.url(),t.match(/Top \d+ [^\n]*/)[0],rows.length,c.length,c.map(r=>r.join('|'))]

